from taf.fdsw.rc.schemas.FDSW24A.autoconnection import Autoconfiguration24A
from taf.fdsw.rc.schemas.base import SchemaField, SchemaObject
from taf.fdsw.rc.schemas.FDSW22A.autoconnection import DnsParameters
from taf.fdsw.rc.schemas.FDSW18A.autoconnection import CertificateServerParameters


class Autoconnection24B(SchemaObject):
    certificate_update = SchemaField(name="certificateUpdate")
    dhcp_server_connection = SchemaField(name="dhcpServerConnection")
    id_entity_connection = SchemaField(name="idEntityConnection")
    ip_config = SchemaField(name="ipConfig")
    mode = SchemaField(name="mode")
    reasoning = SchemaField(name="reasoning")
    status = SchemaField(name="status")

    def __init__(self, certificate_update, dhcp_server_connection, id_entity_connection, ip_config, mode, reasoning,
                 status):
        self.certificate_update = certificate_update
        self.dhcp_server_connection = dhcp_server_connection
        self.id_entity_connection = id_entity_connection
        self.ip_config = ip_config
        self.mode = mode
        self.reasoning = reasoning
        self.status = status
        super(Autoconnection24B, self).__init__()


class PnpStatus24B(SchemaObject):
    autoconnection = SchemaField(name="autoconnection", klass=Autoconnection24B)
    autoconfiguration = SchemaField(name="autoconfiguration", klass=Autoconfiguration24A)

    def __init__(self, autoconnection, autoconfiguration):
        self.autoconnection = autoconnection
        self.autoconfiguration = autoconfiguration
        super(PnpStatus24B, self).__init__()


class ManagementPlaneParameters24B(SchemaObject):
    ip_address = SchemaField(name="ipAddress")
    prefix_length = SchemaField(name="prefixLength")
    gateway = SchemaField(name="gateway")
    vlan_id = SchemaField(name="vlanId")
    ident_server_ip_address = SchemaField(name="identServerIpAddress")
    sec_ip_address = SchemaField(name="secIpAddress")
    sec_prefix_length = SchemaField(name="secPrefixLength")
    sec_vlan_id = SchemaField(name="secVlanId")
    available_eth_ports = SchemaField(name="availableEthPorts")
    selected_eth_port = SchemaField(name="selectedEthPort")
    vpn_gateway_ip_address = SchemaField(name="vpnGatewayIpAddress")
    administrative_state = SchemaField(name="administrativeState")
    inner_mplane_ip_address = SchemaField(name="innerMplaneIpAddress")
    inner_mplane_ip_version = SchemaField(name="innerMplaneIpVersion")
    backup_vpn_gateway_ip_address = SchemaField(name="backupVpnGatewayIpAddress")

    def __init__(
        self,
        ip_address,
        prefix_length,
        gateway,
        vlan_id,
        ident_server_ip_address,
        sec_ip_address,
        sec_prefix_length,
        sec_vlan_id,
        available_eth_ports,
        selected_eth_port,
        vpn_gateway_ip_address,
        administrative_state,
        inner_mplane_ip_address,
        backup_vpn_gateway_ip_address,
        inner_mplane_ip_version

    ):
        self.ip_address = ip_address
        self.prefix_length = prefix_length
        self.gateway = gateway
        self.vlan_id = vlan_id
        self.ident_server_ip_address = ident_server_ip_address
        self.sec_ip_address = sec_ip_address
        self.sec_prefix_length = sec_prefix_length
        self.sec_vlan_id = sec_vlan_id
        self.available_eth_ports = available_eth_ports
        self.selected_eth_port = selected_eth_port
        self.vpn_gateway_ip_address = vpn_gateway_ip_address
        self.administrative_state = administrative_state
        self.inner_mplane_ip_address = inner_mplane_ip_address
        self.backup_vpn_gateway_ip_address = backup_vpn_gateway_ip_address
        self.inner_mplane_ip_version = inner_mplane_ip_version

        super(ManagementPlaneParameters24B, self).__init__()


class AutoConnection24B(SchemaObject):
    pnp_status = SchemaField(name="pnpStatus", klass=PnpStatus24B)
    management_plane_parameters = SchemaField(name="managementPlaneParameters", klass=ManagementPlaneParameters24B)
    certificate_server_parameters = SchemaField(name="certificateServerParameters", klass=CertificateServerParameters)
    dns_parameters = SchemaField(name="dnsParameters", klass=DnsParameters)
    scenario = SchemaField(name='scenario', optional=True)

    def __init__(self, pnp_status, management_plane_parameters, certificate_server_parameters, dns_parameters, scenario=None):
        self.pnp_status = pnp_status
        self.management_plane_parameters = management_plane_parameters
        self.certificate_server_parameters = certificate_server_parameters
        self.dns_parameters = dns_parameters
        self.scenario = scenario

        super(AutoConnection24B, self).__init__()
